import requests
import json

token = dbutils.notebook.entry_point.getDbutils().notebook().getContext().apiToken().get()
host = dbutils.notebook.entry_point.getDbutils().notebook().getContext().apiUrl().get()
headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}

results = {}

url = f"{host}/api/2.0/database/synced_tables"

# spec.source_table_full_name works! Now add primary_key_columns
attempts = [
    {
        "database_instance_name": "mlpab9e4ddc-features-online",
        "logical_database_name": "featuresdb",
        "name": "workspace.mlpab9e4ddc.featuresb1ea93",
        "spec": {
            "scheduling_policy": "TRIGGERED",
            "source_table_full_name": "workspace.mlpab9e4ddc.featuresb1ea93",
            "primary_key_columns": ["row_id"],
        }
    },
    {
        "database_instance_name": "mlpab9e4ddc-features-online",
        "logical_database_name": "featuresdb",
        "name": "workspace.mlpab9e4ddc.featuresb1ea93",
        "spec": {
            "scheduling_policy": "TRIGGERED",
            "source_table_full_name": "workspace.mlpab9e4ddc.featuresb1ea93",
            "primary_key_columns": ["row_id"],
            "timeseries_key": "event_time",
        }
    },
    {
        "database_instance_name": "mlpab9e4ddc-features-online",
        "logical_database_name": "featuresdb",
        "name": "workspace.mlpab9e4ddc.featuresb1ea93",
        "spec": {
            "scheduling_policy": "CONTINUOUS",
            "source_table_full_name": "workspace.mlpab9e4ddc.featuresb1ea93",
            "primary_key_columns": ["row_id"],
            "timeseries_key": "event_time",
        }
    },
]

for i, body in enumerate(attempts):
    resp = requests.post(url, headers=headers, json=body, timeout=15)
    results[f"attempt_{i+1}"] = f"{resp.status_code}: {resp.text[:500]}"
    if resp.status_code in [200, 201]:
        results["SUCCESS"] = body
        break

dbutils.notebook.exit(json.dumps(results))

